// Builds dist/data/stratagem-stats.js (cooldown, call-in time, uses, Eagle rearm
// per stratagem) from db/source/wiki_stratagem_stats.json. Do not edit the output.
// Usage: node scripts/build-stratagem-stats.mjs
import { readFile, writeFile } from 'node:fs/promises';
import { statsOf } from './stratagem-stats-parse.mjs';

const source = JSON.parse(await readFile(new URL('../db/source/wiki_stratagem_stats.json', import.meta.url), 'utf8'));
const stats = Object.fromEntries(Object.entries(source.stratagems).map(([id, entry]) => [id, statsOf(entry)]).filter(([, s]) => s));
const lines = Object.entries(stats).map(([id, s]) => `  ${JSON.stringify(id)}: ${JSON.stringify(s)},`);
const out = `// Generated by scripts/build-stratagem-stats.mjs from db/source/wiki_stratagem_stats.json. Do not edit.
// Base values from each stratagem's wiki page: cooldown and Eagle rearm in seconds,
// call-in time with and without ship modules, uses ('unlimited' when not limited).
export const stratagemStatsCheckedAt = ${JSON.stringify(source.retrievedAt)};
export const stratagemStats = {
${lines.join('\n')}
};
`;
await writeFile(new URL('../dist/data/stratagem-stats.js', import.meta.url), out);
console.log(`${Object.keys(stats).length} stratagems`);
